/**
 * Uninstall Command - Remove AI assistant integrations
 */
import { dirname, join } from "../../../src/platform/compat/path/index.js";
import { cwd as getCwd } from "../../../src/platform/index.js";
import { exists, readDir, remove } from "../../../src/platform/index.js";
import { defineSchema, lazySchema } from "../../../src/schemas/index.js";
import { getEnvironmentConfig } from "../../../src/config/index.js";
import { bold, brand, multiSelect, muted, success, warning } from "../../ui/index.js";
import { AI_TOOLS, getToolById } from "./registry.js";
import { parseTargetFlag } from "./install.js";
import { AIToolIdSchema, UninstallOptionsSchema, } from "./types.js";
export { parseTargetFlag };
export async function findInstalledTools(options, env = getEnvironmentConfig()) {
    const cwd = options.cwd ?? getCwd();
    const homeDir = env.homeDir;
    const installed = [];
    for (const tool of AI_TOOLS) {
        const path = options.global ? join(homeDir, tool.file) : join(cwd, tool.file);
        if (await exists(path))
            installed.push(tool.id);
    }
    return installed;
}
async function isDirEmpty(path) {
    for await (const _entry of readDir(path))
        return false;
    return true;
}
const getAIToolIdArraySchema = defineSchema((v) => v.array(AIToolIdSchema).min(1));
const AIToolIdArraySchema = lazySchema(getAIToolIdArraySchema);
export async function uninstallTargets(targets, options, env = getEnvironmentConfig()) {
    AIToolIdArraySchema.parse(targets);
    const cwd = options.cwd ?? getCwd();
    const homeDir = env.homeDir;
    console.log();
    console.log("  " + bold("Removing AI integrations..."));
    console.log();
    for (const toolId of targets) {
        const tool = getToolById(toolId);
        const dest = options.global ? join(homeDir, tool.file) : join(cwd, tool.file);
        if (!(await exists(dest))) {
            console.log(`  ${warning("!")} ${tool.file} ${muted("not found")}`);
            continue;
        }
        await remove(dest);
        // Try to remove empty parent directories (but not cwd itself)
        try {
            const parent = dirname(dest);
            const baseDir = options.global ? homeDir : cwd;
            if (parent !== baseDir && (await isDirEmpty(parent))) {
                // Node.js requires recursive: true to remove directories
                await remove(parent, { recursive: true });
            }
        }
        catch {
            // Ignore - parent dir might not be empty or might not exist
        }
        console.log(`  ✓ ${tool.file} ${muted("removed")}`);
    }
    console.log();
    console.log("  ✓ AI integrations removed.");
    console.log();
}
export async function uninstallCommand(options = {}) {
    const validated = UninstallOptionsSchema.parse(options);
    const cwd = validated.cwd ?? getCwd();
    if (validated.target) {
        await uninstallTargets(parseTargetFlag(validated.target), { ...validated, cwd });
        return;
    }
    const installed = await findInstalledTools({ cwd, global: validated.global });
    if (installed.length === 0) {
        console.log();
        console.log("  " + muted("No AI tool files found."));
        console.log();
        return;
    }
    const selectOptions = AI_TOOLS.filter((tool) => installed.includes(tool.id))
        .map((tool) => ({
        label: tool.label,
        value: tool.id,
        description: tool.file,
        selected: true,
    }));
    const selected = await multiSelect(selectOptions, {
        title: brand("Remove AI Tool Files"),
        subtitle: "Select files to remove.",
        checkboxStyle: success,
        focusLabelStyle: brand,
        blurLabelStyle: (s) => s,
        descriptionStyle: muted,
    });
    if (!selected?.length) {
        console.log();
        console.log("  " + muted("No files selected."));
        console.log();
        return;
    }
    await uninstallTargets(selected, { ...validated, cwd });
}
